// The plan arrives as text. Parse it and hand one item per step to the
// loop below, so the rover is driven by deterministic n8n execution rather
// than by the model calling tools itself.
const PLACES = ['lake', 'tree', 'house', 'mountain', 'dock', 'center'];
const LEDS = ['red', 'green', 'blue', 'yellow', 'magenta', 'cyan', 'white', 'off'];

const raw = $input.first().json.text ?? $input.first().json.output ?? '';
const match = String(raw).match(/\{[\s\S]*\}/);
if (!match) {
  throw new Error('The model did not return JSON: ' + String(raw).slice(0, 200));
}

const plan = JSON.parse(match[0]);
const steps = (plan.steps || [])
  .filter((s) => PLACES.includes(s.place))
  .slice(0, 6)
  .map((s, i) => ({
    json: {
      index: i + 1,
      place: s.place,
      led: LEDS.includes(s.led) ? s.led : 'blue',
      why: s.why || '',
      summary: plan.summary || '',
      total: 0,
    },
  }));

if (!steps.length) {
  throw new Error('The plan contained no usable steps.');
}
steps.forEach((s) => (s.json.total = steps.length));
return steps;
